   352→  const imageAnimatedStyle = useAnimatedStyle(() => ({
   353→    transform: [
   354→      { scale: imageScale.value },
   355→      { translateX: translateX.value },
   356→      { translateY: translateY.value },
   357→    ],
   358→  }));
