   360→  return (
   361→    <View style={styles.itemContainer}>
   362→      {item.type === 'image' ? (
   363→        <GestureDetector gesture={imageGesture}>
   364→          <Reanimated.View style={[StyleSheet.absoluteFill, imageAnimatedStyle]}>
   365→            <Image
   366→              source={{ uri: mediaUri }}
   367→              style={styles.image}
   368→              contentFit="contain"
   369→              cachePolicy="memory-disk"
   370→              transition={150}
   371→              priority={isActive ? 'high' : 'low'}
   372→              recyclingKey={item.id}
   373→              allowDownscaling
   374→              decodeFormat="rgb"
   375→              placeholder={VIEWER_PLACEHOLDER}
   376→              placeholderContentFit="cover"
   377→            />
   378→          </Reanimated.View>
   379→        </GestureDetector>
