   408→                  fileUri={displayUri}
   409→                  paused={exoPaused}
   410→                  muted={false}
   411→                  onPlayerReady={handlePlaying}
   412→                  onPlayerError={handleError}
   413→                />
   414→              </ExoPlayerBoundary>
