   434→              <Image
   435→                source={cachedThumb ? { uri: cachedThumb } : null}
   436→                style={StyleSheet.absoluteFill}
   437→                contentFit="contain"
   438→                cachePolicy="memory-disk"
   439→                transition={0}
   440→                recyclingKey={item.id}
   441→                placeholder={VIEWER_PLACEHOLDER}
   442→                placeholderContentFit="cover"
   443→              />
   444→            </Animated.View>
   445→
   446→            {/* Retry overlay — only shown on actual playback error */}
   447→            {videoError && (
   448→              <TouchableOpacity
   449→                style={[
   450→                  StyleSheet.absoluteFill,
   451→                  {
   452→                    justifyContent: 'center',
   453→                    alignItems: 'center',
   454→                    backgroundColor: 'rgba(0,0,0,0.65)',
   455→                  },
   456→                ]}
