    76→  // before the timeout fires, so render-flicker false values never reach pause().
    77→  const pauseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    78→
    79→  // ── URI diagnostic log ────────────────────────────────────────────────────
    80→  const uriType = fileUri.startsWith('file://')
    81→    ? 'FILE'
    82→    : fileUri.startsWith('content://')
    83→    ? 'CONTENT⚠️'
    84→    : 'OTHER⚠️';
    85→  console.log('[VideoPlayer] URI type=' + uriType + ' uri=' + fileUri.slice(0, 100));
    86→
    87→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    88→    p.loop = true;
    89→    p.muted = false;
    90→    // timeUpdate fires every 250 ms only when frames are advancing.
    91→    p.timeUpdateEventInterval = 0.25;
    92→    // Sets playWhenReady=true — ExoPlayer starts as soon as the surface
    93→    // attaches.  No further play() calls are needed from JS.
    94→    p.play();
    95→  });
