   101→  }, [onPlaying]);
   102→
   103→  useEffect(() => {
   104→    // ── Mount log ─────────────────────────────────────────────────────────
   105→    _mountedCount++;
   106→    console.log('[VideoPlayer] MOUNTED totalActive=' + _mountedCount + (
   107→      _mountedCount > 1 ? ' ⚠️ MULTIPLE PLAYERS' : ''
   108→    ));
   109→
   110→    const timeUpdateSub = player.addListener('timeUpdate', (event: any) => {
   111→      if ((event.currentTime ?? 0) > 0) confirmPlaying();
   112→    });
   113→
   114→    const statusSub = player.addListener('statusChange', (event: any) => {
