   116→        '[VideoPlayer] statusChange status=' + event.status +
   117→        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?') +
   118→        ' buffered=' + (player.bufferedPosition?.toFixed(2) ?? '?'),
   119→      );
