   153→  // delay means:
   154→  //   • Render flicker (false then true within one batch): timer cancelled, no pause.
   155→  //   • Real swipe-away (stays false): timer fires, player pauses cleanly.
   156→  useEffect(() => {
   157→    if (!didMountRef.current) {
   158→      didMountRef.current = true;
   159→      return;
   160→    }
   161→
   162→    if (pauseTimerRef.current) {
   163→      clearTimeout(pauseTimerRef.current);
   164→      pauseTimerRef.current = null;
   165→    }
   166→
   167→    if (isActive) {
   168→      hasCalledOnPlaying.current = false;
   169→      // Only call play() when the player is not already playing.
   170→      // Calling play() on an already-playing ExoPlayer interrupts its
   171→      // internal buffer-fill pipeline on Android 11+ — that is the
   172→      // play→freeze→play symptom at ~0.7 s.  If isActive briefly flipped
   173→      // false→true (render flicker) and the pause debounce cancelled the
   174→      // pause, the player never stopped; calling play() again here would
   175→      // trigger the same buffer interruption the original didMountRef guard
   176→      // was added to prevent.
   177→      try { if (!player.playing) player.play(); } catch {}
   178→    } else {
   179→      pauseTimerRef.current = setTimeout(() => {
   180→        pauseTimerRef.current = null;
   181→        if (!isActiveRef.current) {
   182→          try { player.pause(); } catch {}
   183→        }
   184→      }, 400);
   185→    }
   186→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   187→
