     1→/**
     2→ * ExoPlayerBoundary — ErrorBoundary wrapper for <ExoPlayerView>.
     3→ *
     4→ * WHY THIS EXISTS:
     5→ * In Fabric (React Native new architecture), a Paper view manager that is
     6→ * absent or missing a Codegen spec throws "View config not found for component
     7→ * ExoPlayerView" during the React reconciler's completeWork phase. That error
     8→ * originates inside the render cycle, so it IS catchable by a class-component
     9→ * ErrorBoundary via getDerivedStateFromError / componentDidCatch.
    10→ *
    11→ * Without this boundary, the crash propagates up and unmounts the entire
    12→ * viewer screen. With it, we catch the throw and route it to onError, which
    13→ * shows the normal retry overlay in ViewerItem — the rest of the UI is
    14→ * completely unaffected.
    15→ *
    16→ * Once a new EAS / local build with ExoPlayerPackage compiled and linked is
    17→ * installed on the device, this boundary is a silent no-op.
    18→ */
    19→import React from 'react';
    20→
    21→interface Props {
    22→  children: React.ReactNode;
    23→  /** Called once when the boundary catches a render error. */
    24→  onError: (message: string) => void;
    25→  /** Changing this key resets the boundary so the player can retry. */
    26→  resetKey?: string;
    27→}
    28→
    29→interface State {
    30→  caught: boolean;
    31→}
    32→
    33→export class ExoPlayerBoundary extends React.Component<Props, State> {
    34→  state: State = { caught: false };
    35→
    36→  static getDerivedStateFromError(): State {
    37→    return { caught: true };
    38→  }
    39→
    40→  componentDidCatch(error: Error) {
    41→    this.props.onError(error?.message ?? 'ExoPlayer unavailable');
    42→  }
    43→
    44→  componentDidUpdate(prevProps: Props) {
    45→    // Allow the boundary to reset when the parent supplies a new key,
    46→    // e.g. after the user taps "retry" which generates a new displayUri.
    47→    if (prevProps.resetKey !== this.props.resetKey && this.state.caught) {
    48→      this.setState({ caught: false });
    49→    }
    50→  }
    51→
    52→  render() {
    53→    // Once caught, render nothing — the parent shows its own error overlay.
    54→    if (this.state.caught) return null;
    55→    return this.props.children;
    56→  }
    57→}
