    // ── Mount log ─────────────────────────────────────────────────────────
    _mountedCount++;
    const mountTag = _mountedCount > 1
      ? ' ⚠️ MULTIPLE PLAYERS — decoder conflict!'
      : ' ✅ sole player';
    console.log(
      '[VideoPlayer] MOUNTED totalActive=' + _mountedCount + mountTag +
      ' uri=' + fileUri.slice(fileUri.lastIndexOf('/') + 1, fileUri.lastIndexOf('/') + 40),
