      console.log(
        '[VideoPlayer] playingChange isPlaying=' + event.isPlaying +
        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?') +
        ' buffered=' + (player.bufferedPosition?.toFixed(2) ?? '?'),
