      statusSub.remove();
      playingSub.remove();
      clearStallTimer();
      if (pauseTimerRef.current) {
        clearTimeout(pauseTimerRef.current);
        pauseTimerRef.current = null;
      }
      try { player.release(); } catch {}
      _mountedCount--;
      console.log('[VideoPlayer] UNMOUNTED totalActive=' + _mountedCount);
    };
